try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  ent_verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='upload'){
   $files=$_FILES['media_files']??null;if(!$files||!is_array($files['name']??null))throw new RuntimeException('Yüklenecek görsel seçin.');
   $ok=0;$errors=[];foreach($files['name'] as $i=>$name){if((int)($files['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;try{ent_media_upload(['name'=>$name,'type'=>$files['type'][$i]??'','tmp_name'=>$files['tmp_name'][$i]??'','error'=>$files['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$files['size'][$i]??0],(string)($_POST['folder']??'Genel'),(string)($_POST['alt_text']??''));$ok++;}catch(Throwable $e){$errors[]=$name.': '.$e->getMessage();}}
   if(!$ok)throw new RuntimeException(implode(' | ',$errors)?:'Görsel yüklenemedi.');ent_redirect('media.php?notice='.rawurlencode($ok.' görsel yüklendi.'.($errors?' '.count($errors).' dosya atlandı.':'')));
  }
  $ids=array_values(array_filter(array_map('intval',(array)($_POST['ids']??[]))));
  if($action==='bulk_move'&&$ids){$folder=mb_substr(trim((string)($_POST['target_folder']??'Genel')),0,100,'UTF-8')?:'Genel';$marks=implode(',',array_fill(0,count($ids),'?'));$pdo->prepare("UPDATE enterprise_media SET folder=?,updated_at=NOW() WHERE id IN ($marks)")->execute(array_merge([$folder],$ids));ent_redirect('media.php?notice='.rawurlencode(count($ids).' görsel taşındı.'));}
  if($action==='bulk_delete'&&$ids){$deleted=0;$blocked=[];foreach($ids as $id){try{ent_media_delete($id);$deleted++;}catch(Throwable $e){$blocked[]=$e->getMessage();}}ent_redirect('media.php?notice='.rawurlencode($deleted.' görsel silindi.'.($blocked?' '.count($blocked).' kullanılan görsel korunarak atlandı.':'')));}
  if($action==='update'){$id=(int)($_POST['id']??0);$folder=mb_substr(trim((string)($_POST['folder']??'Genel')),0,100,'UTF-8')?:'Genel';$alt=mb_substr(trim((string)($_POST['alt_text']??'')),0,255,'UTF-8');$tags=mb_substr(trim((string)($_POST['tags']??'')),0,500,'UTF-8');$fav=isset($_POST['is_favorite'])?1:0;$pdo->prepare('UPDATE enterprise_media SET folder=?,alt_text=?,tags=?,is_favorite=?,updated_at=NOW() WHERE id=?')->execute([$folder,$alt,$tags,$fav,$id]);ent_redirect('media.php?notice='.rawurlencode('Medya bilgileri güncellendi.'));}
  if($action==='delete'){ent_media_delete((int)($_POST['id']??0));ent_redirect('media.php?notice='.rawurlencode('Görsel silindi.'));}
 }
}catch(Throwable $e){$error=$e->getMessage();}
$q=trim((string)($_GET['q']??''));$folder=trim((string)($_GET['folder']??''));$view=(string)($_GET['view']??'all');$sql='SELECT * FROM enterprise_media WHERE 1=1';$params=[];
if($q!==''){$sql.=' AND (original_name LIKE ? OR alt_text LIKE ? OR tags LIKE ? OR folder LIKE ?)';$like='%'.$q.'%';$params=[$like,$like,$like,$like];}if($folder!==''){$sql.=' AND folder=?';$params[]=$folder;}if($view==='favorites')$sql.=' AND is_favorite=1';$sql.=' ORDER BY is_favorite DESC,id DESC LIMIT 500';$st=$pdo->prepare($sql);$st->execute($params);$items=$st->fetchAll(PDO::FETCH_ASSOC);
$folders=$pdo->query('SELECT folder,COUNT(*) total FROM enterprise_media GROUP BY folder ORDER BY folder')->fetchAll(PDO::FETCH_ASSOC);$total=(int)$pdo->query('SELECT COUNT(*) FROM enterprise_media')->fetchColumn();$bytes=(int)$pdo->query('SELECT COALESCE(SUM(file_size),0) FROM enterprise_media')->fetchColumn();
