const drawer=document.querySelector('[data-media-drawer]'),backdrop=document.querySelector('.media-drawer-backdrop');let activeCard=null;function closeDrawer(){drawer?.classList.remove('open');drawer?.setAttribute('aria-hidden','true');if(backdrop)backdrop.hidden=true}function fill(sel,value){const el=drawer?.querySelector(sel);if(el)el.textContent=value||'—'}function openDrawer(card){activeCard=card;drawer?.classList.add('open');drawer?.setAttribute('aria-hidden','false');if(backdrop)backdrop.hidden=false;const d=card.dataset;drawer.querySelector('[data-drawer-image]').src=d.url;drawer.querySelector('[data-drawer-image]').alt=d.alt||d.name;fill('[data-drawer-name]',d.name);fill('[data-drawer-dimensions]',d.dimensions);fill('[data-drawer-size]',d.size);fill('[data-drawer-mime]',d.mime);fill('[data-drawer-folder]',d.folder);fill('[data-drawer-created]',d.created);fill('[data-drawer-usage]',d.usage);drawer.querySelector('[data-drawer-studio]').href='image-studio.php?id='+encodeURIComponent(d.id);drawer.querySelector('[data-drawer-download]').href=d.url;drawer.querySelector('[data-drawer-id]').value=d.id;drawer.querySelector('[data-drawer-delete-id]').value=d.id;drawer.querySelector('[data-drawer-folder-input]').value=d.folder||'Genel';drawer.querySelector('[data-drawer-alt]').value=d.alt||'';drawer.querySelector('[data-drawer-tags]').value=d.tags||'';drawer.querySelector('[data-drawer-favorite]').checked=d.favorite==='1';const del=drawer.querySelector('[data-drawer-delete]');del.disabled=d.used==='1';del.title=d.used==='1'?'Kullanılan görseller silinemez.':''}
document.querySelectorAll('[data-media-card]').forEach(card=>card.querySelector('.media-card-open')?.addEventListener('click',()=>openDrawer(card)));document.querySelectorAll('[data-media-drawer-close]').forEach(x=>x.addEventListener('click',closeDrawer));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});drawer?.querySelector('[data-drawer-copy]')?.addEventListener('click',async e=>{if(!activeCard)return;await navigator.clipboard.writeText(activeCard.dataset.path);const b=e.currentTarget;b.textContent='Kopyalandı ✓';setTimeout(()=>b.textContent='Yolu Kopyala',1200)});</script>
